-- 916: Move the "About IBF Certification" section from short_description
-- into the new per-course `course_<sku>_about_ibf_certification` cms/block,
-- rendered by the new About IBF Certification card after the Certification
-- card. Generated by
-- scripts/local-dev/generate-ibf-about-certification-migration.php.
--
-- Idempotent + partner-safe: SKU-joined exact-byte REPLACE no-ops when the
-- bytes are absent. Literals hex-encoded for apply.php's utf8 connection.
--
-- courses seen: 7  stripped: 7  blocks seeded: 7  skipped: 0

SET @a_sdesc := (SELECT attribute_id FROM eav_attribute WHERE entity_type_id = 4 AND attribute_code = 'short_description');

-- TGS-2022601648
INSERT INTO cms_block (title, identifier, content, creation_time, update_time, is_active)
  SELECT 0x436f75727365205447532d3230323236303136343820e280942041626f7574204942462043657274696669636174696f6e, 0x636f757273655f5447532d323032323630313634385f61626f75745f6962665f63657274696669636174696f6e, , NOW(), NOW(), 1 FROM DUAL
  WHERE NOT EXISTS (SELECT 1 FROM cms_block WHERE identifier = 0x636f757273655f5447532d323032323630313634385f61626f75745f6962665f63657274696669636174696f6e);
INSERT IGNORE INTO cms_block_store (block_id, store_id)
  SELECT block_id, 0 FROM cms_block WHERE identifier = 0x636f757273655f5447532d323032323630313634385f61626f75745f6962665f63657274696669636174696f6e;
UPDATE catalog_product_entity_text t
  JOIN catalog_product_entity e ON e.entity_id = t.entity_id AND e.sku = 0x5447532d32303232363031363438
   SET t.value = REPLACE(t.value, , '')
 WHERE t.attribute_id = @a_sdesc AND t.store_id = 0;


